uv run python -c '
import json
from pydantic import BaseModel, ConfigDict
class M(BaseModel):
    model_config = ConfigDict(strict=True)
    d: str
s = json.loads("\"a\\ud800b\"")
print(repr(s))
try:
    print(repr(M(d=s).d))
except Exception as e: print("python-mode", type(e).__name__, e)
try:
    print(repr(M.model_validate_json(b"{\"d\": \"a\\ud800b\"}").d))
except Exception as e: print("json-mode", type(e).__name__, e)
try: s.encode("utf-8")
except Exception as e: print("encode", type(e).__name__)
'

